"""Least significant bit of a number
       num AND -num = LSB

    Args:
        n ([type]): [description]

    Raises:
        TypeError: [description]

    Returns:
        [type]: [description]
    """
def least_significan_bit(n: Any) -> object {
    if (`type(n) != int) {
        raise TypeError("Number must be Integer.");
    }
    if (n > 0) {
        return (n & -n);
    }
}

