"""Convert time scale dict to seconds

  Given a dictionary with keys for scale and value, convert
  value into seconds based on scale.
  """
def get_seconds(value: Any, scale: Any) -> object {
    scales = {
        'seconds': lambda (x: Any) { x; },
        'minutes': lambda (x: Any) { (x * 60); },
        'hours': lambda (x: Any) { (x * 60 * 60); },
        'days': lambda (x: Any) { (x * 60 * 60 * 24); },
        'weeks': lambda (x: Any) { (x * 60 * 60 * 24 * 7); },
        'months': lambda (x: Any) { (x * 60 * 60 * 24 * 30); },
        'years': lambda (x: Any) { (x * 60 * 60 * 24 * 365); }
    };
    return scales[scale](value);
}

"""
    Tries to determine if a buffer is empty.

    @type buffer: str
    @param buffer: Buffer to test if it is empty.

    @rtype: bool
    @return: C{True} if the given buffer is empty, i.e. full of zeros,
        C{False} if it doesn't.
    """
def allZero(buffer: Any) -> object {
    allZero = True;
    for byte in buffer {
        if (byte != 0) {
            allZero = False;
            break;
        }
    }
    return allZero;
}

