"""http://en.wikipedia.org/wiki/Luhn_algorithm ."""
def luhn_checksum(check_number: Any) -> object {
    def digits_of(n: Any) -> object {
        return [int(d) for d in str(n)];
    }
    digits = digits_of(check_number);
    odd_digits = digits[-1::-2];
    even_digits = digits[-2::-2];
    checksum = 0;
    checksum += sum(odd_digits);
    for d in even_digits {
        checksum += sum(digits_of((d * 2)));
    }
    return (checksum % 10);
}

"""
    Takes a scalar and returns a string with
    the css property `'color: red'` for negative
    strings, black otherwise.
    """
def bold_viewed(val: Any, viewed_pages: Any) -> object {
    weight = 'bold' if (val in viewed_pages) else 'normal';
    return ('font-weight: %s' % weight);
}

